def transform_from_demo(grid):
    """
    Task: For each row, if a background cell is horizontally between two foreground cells,
    change it to the connection color (2).
    Background is the dominant color. Background stays the same.
    Foreground cells stay the same.
    """
    # Determine colors from grid
    color_counts = {}
    for row in grid:
        for cell in row:
            color_counts[cell] = color_counts.get(cell, 0) + 1

    # Background is most common color
    bg = max(color_counts, key=color_counts.get)

    # Find foreground (non-background cells that appear in multiple places)
    fg_candidates = [c for c, cnt in color_counts.items() if c != bg and cnt > 1]
    fg = fg_candidates[0] if fg_candidates else None

    if fg is None:
        return grid

    # The connection color is always 2 (from demo analysis)
    new_fg = 2

    rows = [list(r) for r in grid]
    for r in range(len(rows)):
        for c in range(1, len(rows[0]) - 1):
            if rows[r][c] == bg:
                if rows[r][c-1] == fg and rows[r][c+1] == fg:
                    rows[r][c] = new_fg
    return rows

